// 正常失联释放本次接触并保ready责任；暂失能暂停原Action，永久失效保已交付事实与失败原因。
#include "envoy_task_report_step.hpp"
#include <algorithm>
#include <limits>
namespace hanmo::resident {
Outcome<EnvoyTaskStep> step_envoy_report_action(CommonStore& common,TaskState& tasks,EnvoyTaskState& envoy,const InteractionState& interaction,const InteractionCatalog& catalog,const InteractionAccess& access,const DiplomaticMissionRead& missions,const DiplomacyPresentationRead& presentations,const DiplomaticEnvoyReportRead& reports,const StableId& action_id,const DynamicStepInput& step,const EnvoyReportContinuityRead& continuity_read,const EnvoyReportCommit& receive){
    if(envoy.version!=2)return {false,{},common_failure("EnvoyReportVersionRequired").error};if(common.tick()==std::numeric_limits<Integer>::max()||step.from_tick!=common.tick()||step.to_tick!=step.from_tick+1||std::count(step.existing_action_ids.begin(),step.existing_action_ids.end(),action_id)!=1)return {false,{},common_failure("InvalidEnvoyStepBoundary",action_id,ErrorKind::internal).error};
    EnvoyTaskContract* contract=nullptr;for(auto& row:envoy.envoy_contracts.rows())if(row.second.action&&row.second.action->action_id==action_id){if(contract)return {false,{},common_failure("DuplicateEnvoyAction",action_id,ErrorKind::internal).error};contract=&row.second;}if(!contract)return {false,{},common_failure("UnknownEnvoyAction",action_id,ErrorKind::internal).error};
    const auto& a=contract->acceptance;EnvoyTaskRead read(common,tasks,envoy,missions,presentations,reports);auto source=read.envoy_task_source(a.task_id);if(!source.ok)return {false,{},source.error};auto original=missions.diplomatic_mission_source(a.mission_authority_fact_id);if(!original.ok)return {false,{},original.error};const auto work=original.value.report_work_ticks;const auto* current=common.action(action_id);const auto& ctx=contract->action->context;const auto* actor=common.actor(a.envoy_actor_id);const auto* provider=common.actor(ctx.provider_actor_id);
    if(source.value.task_status!="ready"||!source.value.delivery||source.value.completion||!a.return_report_required||contract->action->kind!=EnvoyTaskActionKind::report||!current||current->kind!="envoy_report"||current->actor_id!=a.envoy_actor_id||work<1||current->remaining_ticks<1||current->remaining_ticks>work||current->start_tick<source.value.delivery->completed_tick||current->start_tick>common.tick()||common.tick()-current->start_tick<work-current->remaining_ticks||!face_to_face_contact_context_valid(ctx)||ctx.place_id!=a.report_site_id||!actor||!provider||actor->id==provider->id||actor->action_id!=action_id||provider->action_id!=action_id||current->participants.size()!=2||std::count(current->participants.begin(),current->participants.end(),actor->id)!=1||std::count(current->participants.begin(),current->participants.end(),provider->id)!=1)return {false,{},common_failure("InvalidEnvoyReportStep",action_id,ErrorKind::internal).error};
    if(!continuity_read)return {false,{},common_failure("MissingEnvoyReportContinuityService",a.task_id,ErrorKind::internal).error};const auto action=*current;
    auto decision=[&](const DiplomaticMissionContinuity& d)->Outcome<EnvoyTaskStep>{
        if(d.kind==DiplomaticMissionContinuityKind::terminate_envoy_dead){if(actor->alive)return {false,{},common_failure("EnvoyDeathSourceMismatch",action_id,ErrorKind::internal).error};return interrupt_envoy_handover(common,tasks,*contract,action,work,step.to_tick,"EnvoyDead",d.code.empty()?"EnvoyDead":d.code,true,d.cause_fact_id);}
        if(d.kind==DiplomaticMissionContinuityKind::terminate_principal_dissolved)return interrupt_envoy_handover(common,tasks,*contract,action,work,step.to_tick,"PrincipalDissolved",d.code.empty()?"PrincipalDissolved":d.code,true,d.cause_fact_id);
        if(d.kind==DiplomaticMissionContinuityKind::continue_work)return {true,{false,false,true,a.task_id,{},{}},{}};
        if(d.kind!=DiplomaticMissionContinuityKind::pause_envoy&&d.kind!=DiplomaticMissionContinuityKind::needs_reassignment)return {false,{},common_failure("UnknownEnvoyContinuity",action_id,ErrorKind::internal).error};contract->pending_code=d.code.empty()?(d.kind==DiplomaticMissionContinuityKind::pause_envoy?"EnvoyUnavailable":"NeedsReassignment"):d.code;return {true,{true,false,true,a.task_id,contract->pending_code,{}},{}};
    };
    auto continuity=continuity_read(a,*source.value.delivery);if(!continuity.ok)return {false,{},continuity.error};auto allowed=decision(continuity.value);if(!allowed.ok||allowed.value.suspended||allowed.value.action_finished)return allowed;if(!actor->alive||!actor->available)return {false,{},common_failure("EnvoyContinuityMismatch",action_id,ErrorKind::internal).error};
    if(!access.resolve_location||!access.role||!access.battle_occupied)return {false,{},common_failure("MissingEnvoyContactAccess",action_id,ErrorKind::internal).error};if(access.battle_occupied(actor->id)||access.battle_occupied(provider->id)){contract->pending_code="BattlePending";return {true,{true,false,true,a.task_id,"BattlePending",{}},{}};}
    auto at_site=[&](const StableId& id){auto location=access.resolve_location(id);const auto* place=std::get_if<SettlementLocation>(&location);return place&&place->place_id==a.report_site_id;};
    if(!provider->alive||!provider->available||!at_site(actor->id)||!at_site(provider->id))return interrupt_envoy_handover(common,tasks,*contract,action,work,step.to_tick,"RenewContact","EnvoyReportContactUnavailable",false,{});
    if(!ctx.kind){const auto* role=catalog.common?catalog.common->roles.find(ctx.role_id):nullptr;if(!role||role->place_id!=ctx.place_id)return {false,{},common_failure("InvalidEnvoyAuthoredContact",action_id,ErrorKind::internal).error};auto assigned=access.role(ctx.role_id);if(!assigned||!assigned->enabled||assigned->actor_id!=provider->id)return interrupt_envoy_handover(common,tasks,*contract,action,work,step.to_tick,"RenewContact","EnvoyReportRoleChanged",false,{});}
    auto contact=validate_interaction(common,interaction,catalog,access,actor->id,ctx,{},action_id);if(!contact.ok)return {false,{},contact.error};contract->pending_code.clear();ActionMutation decrement;decrement.action=action;decrement.remaining_ticks=action.remaining_ticks-1;auto changed=common.apply_action(decrement);if(!changed.ok)return {false,{},changed.error};if(action.remaining_ticks>1)return {true,{false,false,true,a.task_id,{},{}},{}};
    auto attempt=finish_envoy_report_in_candidate(common,tasks,envoy,interaction,catalog,access,missions,presentations,reports,a.task_id,action_id,step.to_tick,receive);if(!attempt.ok)return {false,{},attempt.error};
    if(attempt.value.kind==DiplomaticEnvoyReportAttemptKind::reported)return {true,{false,true,true,a.task_id,{},contract->completion->fact_id},{}};
    if(attempt.value.kind==DiplomaticEnvoyReportAttemptKind::renew_contact)return interrupt_envoy_handover(common,tasks,*contract,*common.action(action_id),work,step.to_tick,"RenewContact",attempt.value.code,false,{});
    // 接收资格复核暂停本半日时保原余量；完成后的合法报告不会走回未完成分支。
    ActionMutation restore;restore.action=action;restore.remaining_ticks=action.remaining_ticks;changed=common.apply_action(restore);if(!changed.ok)return {false,{},changed.error};return decision(*attempt.value.continuity);
}
Status reconcile_envoy_reports_boundary(CommonStore& common,TaskState& tasks,EnvoyTaskState& envoy,const DiplomaticMissionRead& missions,const DiplomacyPresentationRead& presentations,const DynamicStepInput& step,const EnvoyReportContinuityRead& continuity_read){
    if(envoy.version!=2)return common_failure("EnvoyReportVersionRequired");if(step.from_tick==std::numeric_limits<Integer>::max()||step.to_tick!=step.from_tick+1||common.tick()!=step.to_tick)return common_failure("InvalidEnvoyStepBoundary");if(!continuity_read)return common_failure("MissingEnvoyReportContinuityService",{},ErrorKind::internal);
    EnvoyTaskRead read(common,tasks,envoy,missions,presentations);
    for(auto& row:envoy.envoy_contracts.rows()){
        auto& contract=row.second;if(contract.action||contract.completion||!contract.delivery||!contract.acceptance.return_report_required)continue;auto source=read.envoy_task_source(row.first);if(!source.ok)return {false,{},source.error};const auto& a=source.value.acceptance;auto continuity=continuity_read(a,*source.value.delivery);if(!continuity.ok)return {false,{},continuity.error};const auto& d=continuity.value;
        if(d.kind==DiplomaticMissionContinuityKind::continue_work){const bool renew=!contract.interruptions.empty()&&contract.interruptions.back().action_kind=="envoy_report"&&contract.interruptions.back().reason=="RenewContact";contract.pending_code=renew?StableId{"EnvoyReportContactRenewalRequired"}:StableId{};continue;}
        if(d.kind==DiplomaticMissionContinuityKind::pause_envoy||d.kind==DiplomaticMissionContinuityKind::needs_reassignment){contract.pending_code=d.code.empty()?(d.kind==DiplomaticMissionContinuityKind::pause_envoy?"EnvoyUnavailable":"NeedsReassignment"):d.code;continue;}
        if(d.kind!=DiplomaticMissionContinuityKind::terminate_envoy_dead&&d.kind!=DiplomaticMissionContinuityKind::terminate_principal_dissolved)return common_failure("UnknownEnvoyContinuity",row.first,ErrorKind::internal);
        const auto* actor=common.actor(a.envoy_actor_id);if(!actor||(d.kind==DiplomaticMissionContinuityKind::terminate_envoy_dead&&actor->alive))return common_failure("EnvoyDeathSourceMismatch",row.first,ErrorKind::internal);if(d.cause_fact_id&&(d.cause_fact_id->empty()||!common.state().facts.find(*d.cause_fact_id)))return common_failure("MissingEnvoyInterruptionCause",row.first,ErrorKind::internal);
        auto id=common.next_id("envoy_failed");if(!id.ok)return {false,{},id.error};EnvoyTaskCompletion final;final.fact_id=id.value;final.task_id=a.task_id;final.contract_id=a.contract_id;final.acceptance_fact_id=a.fact_id;final.delivery_fact_id=contract.delivery->fact_id;final.result=EnvoyTaskResult::failed;final.completed_tick=common.tick();final.reason=d.kind==DiplomaticMissionContinuityKind::terminate_envoy_dead?"EnvoyDead":"PrincipalDissolved";auto wrote=common.append_fact({final.fact_id,"envoy_task_failed","tasks"});if(!wrote.ok)return wrote;contract.completion=std::move(final);contract.pending_code.clear();auto* task=tasks.tasks.find(row.first);task->status="failed";task->settlement_id=id.value;task->reported_tick=common.tick();
    }
    return common_success();
}
}
